import json
import os

# The user's own override bios and short-bio file are read from the live test's folder when it is on this PC (they are
# never copied into the repository); a test that needs them is skipped without them.
LIVE7 = os.path.join(os.environ.get('MLW_EVIDENCE', ''), r'lw-live-test-7-2026-11-15')


def _bio(file):
    try:
        with open(os.path.join(LIVE7, 'character_overrides-before', file + '.json'), encoding='utf-8-sig') as f:
            data = json.load(f)
        return (data[0] if isinstance(data, list) else data)['bio']
    except (OSError, ValueError, KeyError, IndexError):
        return None


def _bios_after():
    try:
        with open(os.path.join(LIVE7, 'test-artifacts', 'living_world_bios.after.json'), encoding='utf-8') as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


